(()=>{
const $=id=>document.getElementById(id),money=n=>Number(n).toLocaleString("pl-PL",{minimumFractionDigits:2,maximumFractionDigits:2})+" zł",number=(n,d=3)=>Number(n).toLocaleString("pl-PL",{maximumFractionDigits:d});
const allData=[];let period=7,chartPoints=[],homePeriod=30,homeHistory=[];const formatDate=s=>new Date(s+"T12:00:00Z").toLocaleDateString("pl-PL",{day:"2-digit",month:"2-digit"});
function drawChart(){if(!allData.length)return;const source=allData.slice(-period),onlyCurrent=source.length===1,data=onlyCurrent?[source[0],source[0]]:source,svg=$('chart'),width=Math.max(260,svg.parentElement.clientWidth),height=270,L=52,R=24,T=20,B=40;svg.setAttribute('viewBox',`0 0 ${width} ${height}`);const min=Math.floor((Math.min(...data.map(d=>d.value))-.04)*10)/10,max=Math.ceil((Math.max(...data.map(d=>d.value))+.04)*10)/10;const x=i=>L+i/(data.length-1)*(width-L-R),y=n=>T+(max-n)/(max-min||1)*(height-T-B);chartPoints=data.map((d,i)=>({...d,x:x(i),y:y(d.value)}));let markup=`<title>${onlyCurrent?'Aktualny kurs srebra — historia chwilowo niedostępna':'Historia kursu srebra'}</title>`;for(let i=0;i<5;i++){const value=min+(max-min)*i/4,yy=y(value);markup+=`<line x1="${L}" x2="${width-R}" y1="${yy}" y2="${yy}" class="gridline"/><text x="${L-10}" y="${yy+4}" text-anchor="end">${value.toFixed(2).replace('.',',')}</text>`;}const indices=[0,Math.round((data.length-1)/3),Math.round((data.length-1)*2/3),data.length-1];for(const i of indices)markup+=`<text x="${x(i)}" y="${height-12}" text-anchor="${i===0?'start':i===data.length-1?'end':'middle'}">${formatDate(data[i].date)}</text>`;const points=chartPoints.map(p=>`${p.x},${p.y}`).join(' ');markup+=`<polygon points="${L},${height-B} ${points} ${width-R},${height-B}" class="chart-fill"/><polyline points="${points}" class="chart-line"/><circle cx="${width-R}" cy="${y(data.at(-1).value)}" r="5" class="chart-point"/><text x="${L}" y="13" class="axis-label">zł / g</text>${onlyCurrent?`<text x="${width/2}" y="${height/2}" text-anchor="middle" class="chart-notice">Historia notowań jest chwilowo niedostępna</text>`:''}<line id="chart-guide" x1="0" x2="0" y1="${T}" y2="${height-B}" hidden class="chart-guide"/>`;svg.innerHTML=markup;$('chart-range').textContent=onlyCurrent?`${source[0].date} · bieżący kurs`:`${formatDate(data[0].date)}–${formatDate(data.at(-1).date)}.2026`;$('chart-last').textContent=money(data.at(-1).value);$('chart-table').innerHTML=source.map(d=>`<tr><td>${d.date}</td><td>${number(d.value)} zł</td></tr>`).join('');$('chart-tooltip').hidden=true;}
  const renderHomeChart=history=>{
    const svg=document.getElementById('desktop-market-line');
    if(!svg)return;
    const selected=history.slice(-Math.min(homePeriod,history.length));
    const source=(selected.length===1?history.slice(-2):selected).map(item=>({date:item.date,value:Number(item.value)})),onlyCurrent=source.length===1,data=onlyCurrent?[source[0],source[0]]:source;
    const W=Math.max(520,svg.parentElement.clientWidth),H=270,L=52,R=24,T=20,B=40,values=data.map(item=>item.value);
    const min=Math.floor((Math.min(...values)-.04)*10)/10,max=Math.ceil((Math.max(...values)+.04)*10)/10;
    const x=index=>L+index/(data.length-1)*(W-L-R),y=value=>T+(max-value)/(max-min||1)*(H-T-B);
    const points=data.map((item,index)=>`${x(index)},${y(item.value)}`).join(' ');
    let markup='<title>Historia kursu srebra z ostatnich 30 dni</title><defs><linearGradient id="home-area" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#8bc6a8" stop-opacity=".42"/><stop offset="1" stop-color="#8bc6a8" stop-opacity=".03"/></linearGradient></defs>';
    for(let i=0;i<5;i++){const value=min+(max-min)*i/4,yy=y(value);markup+=`<line class="home-grid" x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}"/><text class="home-axis" x="${L-10}" y="${yy+4}" text-anchor="end">${value.toFixed(2).replace('.',',')}</text>`;}
    [0,Math.round((data.length-1)/3),Math.round((data.length-1)*2/3),data.length-1].forEach(index=>{const label=data[index].date.slice(5).replace('-', '.');markup+=`<text class="home-axis" x="${x(index)}" y="${H-10}" text-anchor="${index===0?'start':index===data.length-1?'end':'middle'}">${label}</text>`;});
    markup+=`<polygon points="${L},${H-B} ${points} ${W-R},${H-B}" fill="url(#home-area)"/><polyline points="${points}" class="home-line"/><circle cx="${x(data.length-1)}" cy="${y(data.at(-1).value)}" r="5" class="home-point"/><text class="home-unit" x="${L}" y="13">zł / g</text>${onlyCurrent?`<text x="${W/2}" y="${H/2}" text-anchor="middle" class="home-notice">Historia notowań jest chwilowo niedostępna</text>`:''}`;
    svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.setAttribute('preserveAspectRatio','none');svg.innerHTML=markup;const range=document.getElementById('home-chart-range');if(range)range.textContent=`${data[0].date} – ${data.at(-1).date}`;
  };

(function attachCharts(){document.querySelectorAll('[data-live-period]').forEach(b=>b.onclick=()=>{period=Number(b.dataset.livePeriod);document.querySelectorAll('[data-live-period]').forEach(e=>e.setAttribute('aria-pressed',String(e===b)));drawChart();});const svg=$('chart');if(svg){svg.addEventListener('pointermove',e=>{if(!chartPoints.length)return;const bounds=svg.getBoundingClientRect(),pos=e.clientX-bounds.left;const point=chartPoints.reduce((a,b)=>Math.abs(a.x-pos)<Math.abs(b.x-pos)?a:b);const tip=$('chart-tooltip');tip.textContent=point.date+' · '+number(point.value)+' zł/g';tip.hidden=false;tip.style.left=Math.max(0,Math.min(point.x-65,bounds.width-185))+'px';tip.style.top='10px';});svg.addEventListener('pointerleave',()=>{$('chart-tooltip').hidden=true;});new ResizeObserver(drawChart).observe(svg.parentElement);}document.addEventListener('silver-prices-ready',e=>{const h=e.detail.metals?.silver?.history;if(!Array.isArray(h))return;allData.splice(0,allData.length,...h.map(p=>({date:p.date,value:Number(p.value)})).filter(p=>Number.isFinite(p.value)));if(svg)drawChart();if(typeof renderHomeChart==='function'){homeHistory=allData;renderHomeChart(homeHistory);}const spot=$('desktop-spot'),change=$('desktop-change');if(spot)spot.textContent=money(e.detail.metals.silver.spot)+' / g';if(change)change.textContent=(e.detail.metals.silver.change>=0?'▲':'▼')+' '+number(Math.abs(e.detail.metals.silver.change),2)+'% dzisiaj';});document.querySelectorAll('[data-home-period]').forEach(b=>b.onclick=()=>{homePeriod=Number(b.dataset.homePeriod);document.querySelectorAll('[data-home-period]').forEach(e=>e.setAttribute('aria-pressed',String(e===b)));if(homeHistory.length)renderHomeChart(homeHistory);});})();
})();

